package com.nimbusbill.customer.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="invoice_line_items") public class InvoiceLineItem {
 @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(optional=false) @JoinColumn(name="invoice_id") private Invoice invoice; @OneToOne(optional=false) @JoinColumn(name="billing_run_item_id",unique=true) private BillingRunItem billingRunItem; @Column(name="transaction_id",nullable=false) private UUID transactionId; @Column(name="product_code",nullable=false,length=30) private String productCode; @Column(nullable=false,length=200) private String description; @Column(name="base_amount",nullable=false,precision=19,scale=4) private BigDecimal baseAmount; @Column(name="tax_amount",nullable=false,precision=19,scale=4) private BigDecimal taxAmount; @Column(name="total_amount",nullable=false,precision=19,scale=4) private BigDecimal totalAmount; @Column(nullable=false,length=3) private String currency; @Column(name="created_at",nullable=false) private Instant createdAt; @PrePersist void create(){createdAt=Instant.now();}
 public UUID getId(){return id;} public void setInvoice(Invoice v){invoice=v;} public void setBillingRunItem(BillingRunItem v){billingRunItem=v;} public UUID getTransactionId(){return transactionId;} public void setTransactionId(UUID v){transactionId=v;} public String getProductCode(){return productCode;} public void setProductCode(String v){productCode=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public BigDecimal getBaseAmount(){return baseAmount;} public void setBaseAmount(BigDecimal v){baseAmount=v;} public BigDecimal getTaxAmount(){return taxAmount;} public void setTaxAmount(BigDecimal v){taxAmount=v;} public BigDecimal getTotalAmount(){return totalAmount;} public void setTotalAmount(BigDecimal v){totalAmount=v;} public String getCurrency(){return currency;} public void setCurrency(String v){currency=v;}
}
